\title{Functoriality, the $\Ztwo$-Index, and the Exact Enumeration of Antipodal Maps of Cross-Polytope Spheres}
\author{Aristotle}
\date{July 14, 2026}

\begin{document}
\begin{abstract}
We study antipodal (that is, $\Ztwo$-equivariant) simplicial maps between combinatorial spheres realized as boundaries of cross-polytopes. The boundary of the $(n+1)$-dimensional cross-polytope furnishes a triangulated $n$-sphere $S^n$ with $2(n+1)$ vertices---a positive and a negative pole for each of $n+1$ coordinate axes---carrying a free $\Ztwo$-action given by the antipode. Building on the existence dichotomy that an antipodal map $S^m \to S^n$ exists iff $m \le n$, we develop the structural and enumerative theory of these maps. First, antipodal maps compose, so the family of spheres forms a thin category whose reachability relation is exactly $m \le n$. Second, the $\Ztwo$-index---the least target dimension into which $S^m$ admits an antipodal map---equals $m$, coinciding with the coindex, so the index--coindex gap vanishes. Third, we establish a bijection identifying an antipodal map with an injection of coordinate axes together with an independent sign vector, yielding the exact count $\#\{\text{antipodal maps } S^m \to S^n\} = (n+1)^{\underline{\,m+1\,}}\cdot 2^{m+1}$, where $(n+1)^{\underline{\,m+1\,}}$ is the falling factorial. The diagonal recovers the order $2^{n+1}(n+1)!$ of the hyperoctahedral group $B_{n+1}$, and positivity of the count is exactly the Borsuk--Ulam threshold $m \le n$.
\end{abstract}
\maketitle

\section{Introduction}
The Borsuk--Ulam theorem asserts that there is no continuous antipodal map from the $m$-sphere to the $n$-sphere when $m > n$. It underlies lower bounds for chromatic numbers, fair-division and necklace-splitting theorems, and much of topological combinatorics. Its natural invariants are the $\Ztwo$-\emph{index} and $\Ztwo$-\emph{coindex} of a free $\Ztwo$-space: the smallest sphere the space maps into, and the largest sphere that maps into the space.

For general free $\Ztwo$-complexes these invariants are subtle: they need not agree, and the bound ``coindex $\le$ dimension'' requires the full strength of Borsuk--Ulam (equivalently, Tucker's lemma). We show that in the \emph{cross-polytope model}---spheres are boundaries of orthoplexes and maps are antipodal simplicial maps---the theory collapses to exact combinatorics, and we extract a complete quantitative description: (1) functoriality, (2) the coincidence index $=$ coindex, (3) an exact enumeration, and (4) coherent behaviour under suspension.

\section{The cross-polytope model}

\begin{definition}[Combinatorial sphere]
For $n \in \Nat$, the \emph{combinatorial $n$-sphere} $S^n$ is the boundary complex of the $(n+1)$-dimensional cross-polytope. Its vertex set is $V(S^n) = \{0,\dots,n\}\times\{+,-\}$: each of the $n+1$ coordinate axes $i$ contributes a positive pole $(i,+) = +e_i$ and a negative pole $(i,-) = -e_i$.
\end{definition}

\begin{definition}[Faces]
A subset $\sigma \subseteq V(S^n)$ is a \emph{face} iff it contains at most one pole of each axis (never both $(i,+)$ and $(i,-)$). The maximal faces are the sign-choices $\{(0,\varepsilon_0),\dots,(n,\varepsilon_n)\}$, the $2^{n+1}$ facets.
\end{definition}

\begin{definition}[Antipode]
The \emph{antipodal map} $\alpha(i,\varepsilon) = (i,-\varepsilon)$ is a free simplicial involution, making $S^n$ a free $\Ztwo$-complex.
\end{definition}

\begin{definition}[$\Ztwo$-map]
A \emph{$\Ztwo$-map} $F : S^m \to S^n$ is a vertex map with (Equivariance) $F(\alpha v) = \alpha F(v)$ and (Simpliciality) the image of every face is a face. Write $\Zmap(m,n)$ for the set of such maps.
\end{definition}

\begin{definition}[Positive-vertex data, induced map, coordinate map]
For equivariant $F$, its \emph{positive-vertex data} is $g_F(i) = F(i,+)$. Any $g:\{0,\dots,m\}\to V(S^n)$ \emph{induces} the unique equivariant $\operatorname{ind}(g)$ with $\operatorname{ind}(g)(i,\pm) = \alpha^{[\pm]} g(i)$. Its \emph{coordinate map} $\coord(g)(i)$ records only the axis of $g(i)$.
\end{definition}

\begin{lemma}[Reconstruction]
Every equivariant map $F$ equals $\operatorname{ind}(g_F)$.
\end{lemma}
\begin{proof}
On positive poles this is the definition; on negative poles, $F(i,-)=\alpha F(i,+)=\alpha g_F(i)=\operatorname{ind}(g_F)(i,-)$.
\end{proof}

\begin{lemma}[Simpliciality criterion]\label{lem:simp}
The induced map $\operatorname{ind}(g)$ is simplicial iff $\coord(g)$ is injective.
\end{lemma}
\begin{proof}
A maximal face upstairs is a full sign-choice over all $m+1$ axes; its image uses target axes $\coord(g)(0),\dots,\coord(g)(m)$, which forms a face iff these are pairwise distinct. Signs are irrelevant, since a face constraint only forbids two poles of the \emph{same} axis.
\end{proof}

\section{Functoriality}

\begin{theorem}[Composition]
Given $G \in \Zmap(n,p)$ and $F \in \Zmap(m,n)$, the composite $G\circ F$ lies in $\Zmap(m,p)$.
\end{theorem}
\begin{proof}
Equivariance: $(G\circ F)(\alpha v)=G(\alpha F(v))=\alpha G(F(v))$. Simpliciality: $F(\sigma)$ is a face by simpliciality of $F$, then $G(F(\sigma))$ is a face by simpliciality of $G$.
\end{proof}

\begin{corollary}[Transitivity of existence]
If $\Zmap(n,p)$ and $\Zmap(m,n)$ are nonempty, so is $\Zmap(m,p)$.
\end{corollary}
Composition is associative with identity units, so the spheres form a thin category; by the existence dichotomy the reachability relation is exactly $\le$.

\section{The $\Ztwo$-index and its coincidence with the coindex}

\begin{definition}
$\coind(S^n) = \sup\{m : \Zmap(m,n)\ne\varnothing\}$ and $\ind(S^m) = \inf\{n : \Zmap(m,n)\ne\varnothing\}$.
\end{definition}

\begin{lemma}[Admissible targets]\label{lem:adm}
$\{n : \Zmap(m,n)\ne\varnothing\} = \{m,m+1,\dots\}$.
\end{lemma}
\begin{proof}
Immediate from the existence dichotomy $\Zmap(m,n)\ne\varnothing \iff m\le n$.
\end{proof}

\begin{theorem}[Index of a sphere]
$\ind(S^m) = m$.
\end{theorem}
\begin{proof}
By Lemma~\ref{lem:adm} the admissible set is $\{n : n\ge m\}$, whose infimum is $m$.
\end{proof}

\begin{theorem}[Index--coindex coincidence]
For every $n$, $\ind(S^n) = \coind(S^n) = n$; the index--coindex gap of a cross-polytope sphere is zero.
\end{theorem}

\begin{remark}
This vanishing is special to spheres. For a general free simplicial $\Ztwo$-complex $K$ the coindex is not determined by dimension, the invariants can differ, and $\coind(K)\le\dim K$ genuinely requires Tucker's lemma.
\end{remark}

\section{The enumeration bijection}

\begin{theorem}[Structure of $\Ztwo$-maps]\label{thm:struct}
There is a bijection
\[
\Phi : \Zmap(m,n) \xrightarrow{\ \sim\ } \bigl(\{0,\dots,m\}\hookrightarrow\{0,\dots,n\}\bigr)\times\bigl(\{0,\dots,m\}\to\{+,-\}\bigr),
\]
$F\mapsto(\coord(g_F),\operatorname{sign}(g_F))$.
\end{theorem}
\begin{proof}
$F$ is determined by $g_F$ (Reconstruction), which is equivalent to the pair (coordinate map, sign function). By Lemma~\ref{lem:simp} the coordinate map is injective iff the induced map is simplicial; as $F$ is simplicial, $\coord(g_F)$ is injective. Conversely, any (injection, sign) pair reassembles into $g$ with injective coordinate map, hence a $\Ztwo$-map $\operatorname{ind}(g)$; the two constructions are mutually inverse.
\end{proof}

\begin{corollary}
$\Zmap(m,n)$ is finite.
\end{corollary}

\section{Exact enumeration}

\begin{theorem}[Exact count]\label{thm:count}
For all $m,n\in\Nat$,
\[
\#\Zmap(m,n) = (n+1)^{\underline{\,m+1\,}}\cdot 2^{m+1},
\]
where $(n+1)^{\underline{\,m+1\,}} = (n+1)n(n-1)\cdots(n-m+1)$.
\end{theorem}
\begin{proof}
By Theorem~\ref{thm:struct} the count is (number of injections $\{0,\dots,m\}\hookrightarrow\{0,\dots,n\}$) $\times$ (number of sign vectors). The former is the falling factorial; the latter is $2^{m+1}$.
\end{proof}

\begin{theorem}[Quantitative Borsuk--Ulam]
$\#\Zmap(m,n) > 0 \iff m \le n$, and $\#\Zmap(m,n) = 0 \iff n < m$. In particular $\#\Zmap(n+1,n)=0$.
\end{theorem}
\begin{proof}
The falling factorial $(n+1)^{\underline{\,m+1\,}}$ is positive iff $m+1\le n+1$; the power of two is always positive.
\end{proof}

\begin{theorem}[Self-maps and the hyperoctahedral group]
$\#\Zmap(n,n) = (n+1)!\cdot 2^{n+1}$, the order of the hyperoctahedral group $B_{n+1}$ of signed permutations.
\end{theorem}
\begin{proof}
Set $m=n$ in Theorem~\ref{thm:count}; the falling factorial becomes $(n+1)!$.
\end{proof}

\begin{center}
\begin{tabular}{c|ccccc}
$m\backslash n$ & 0 & 1 & 2 & 3 & 4\\\hline
0 & 2 & 4 & 6 & 8 & 10\\
1 & 0 & 8 & 24 & 48 & 80\\
2 & 0 & 0 & 48 & 192 & 480\\
\end{tabular}
\end{center}
The zeros below the diagonal are Borsuk--Ulam; the diagonal $2,8,48,384,\dots$ is $2^{n+1}(n+1)!$.

\section{Interaction with the suspension tower}
The \emph{suspension} $\Sigma$ adds one coordinate axis with two new poles, sending $S^n$ to $S^{n+1}$; on maps it extends $F:S^m\to S^n$ to $\Sigma F:S^{m+1}\to S^{n+1}$ by matching the new axes with matching sign.

\begin{theorem}[Suspension preserves excess]
For all $m,n,k$, $\Zmap(m+k,n+k)\ne\varnothing \iff \Zmap(m,n)\ne\varnothing$. Equivalently the excess $n-m$ is suspension-invariant, and each rung of the tower is Borsuk--Ulam sharp.
\end{theorem}
\begin{proof}
Both sides equal $m\le n$ since $m+k\le n+k\iff m\le n$; $\Sigma$ realizes the forward direction and axis-restriction the backward one.
\end{proof}

\section{Discussion and future work}
The octahedral model is maximally rigid: functorial reachability ordered by $\le$, a vanishing index--coindex gap, and a map-count factoring as a falling factorial times a power of two---the enumerative signature of decoupled axis and sign choices. This makes the family a calibrated baseline: a positive index--coindex gap or a count not of this shape certifies non-octahedral structure.

Future directions include: engineering complexes with a strictly positive index--coindex gap growing linearly in the gap size; characterizing the falling-factorial signature as detecting joins of copies of $S^0$; upgrading suspension to an enumerative bijection onto pole-fixing maps; recovering $\coind\le\dim$ for general $K$ via Tucker's lemma; and connecting the coindex of neighbourhood/box complexes to chromatic lower bounds.

