"""Closed-form vs. brute-force validation of the antipodal-map count.

Enumerates all antipodal simplicial maps S^m -> S^n explicitly (as an injection of
axes together with a free sign vector) and checks the count against the closed form
#maps(m,n) = (n+1)^{falling m+1} * 2^{m+1}.
"""
from __future__ import annotations
from itertools import permutations, product
from typing import Iterator, Tuple

Vertex = Tuple[int, int]
PosData = Tuple[Vertex, ...]


def falling_factorial(a: int, k: int) -> int:
    r = 1
    for i in range(k):
        r *= (a - i)
    return r


def count_closed_form(m: int, n: int) -> int:
    return falling_factorial(n + 1, m + 1) * 2 ** (m + 1)


def enumerate_maps(m: int, n: int) -> Iterator[PosData]:
    for axis_choice in permutations(range(n + 1), m + 1):
        for sign_choice in product((+1, -1), repeat=m + 1):
            yield tuple((axis_choice[i], sign_choice[i]) for i in range(m + 1))


def brute_force_count(m: int, n: int) -> int:
    return sum(1 for _ in enumerate_maps(m, n))


if __name__ == "__main__":
    for m in range(4):
        for n in range(4):
            cf = count_closed_form(m, n)
            bf = brute_force_count(m, n)
            assert cf == bf, (m, n, cf, bf)
            print(f"m={m} n={n}: {cf} (verified)")

"""Index, coindex, and the vanishing gap for cross-polytope spheres.

Using only the existence test m <= n, computes coind(S^n) (largest source that
maps in) and ind(S^n) (smallest target it maps out into), showing both equal n.
Also verifies suspension preserves the excess n - m.
"""
from __future__ import annotations


def exists_map(m: int, n: int) -> bool:
    return m <= n


def coindex(n: int, cap: int = 100) -> int:
    return max(m for m in range(cap + 1) if exists_map(m, n))


def index(m: int, cap: int = 100) -> int:
    return min(n for n in range(cap + 1) if exists_map(m, n))


if __name__ == "__main__":
    for n in range(8):
        c, i = coindex(n), index(n)
        assert c == n == i
        print(f"n={n}: coind = {c}, ind = {i}, gap = {i - c}")
    for m, n in [(1, 4), (2, 2), (0, 3)]:
        for k in range(4):
            assert exists_map(m, n) == exists_map(m + k, n + k)
    print("Suspension preserves excess n - m for all tested (m, n, k).")

