from typing import List


def falling_factorial(a: int, k: int) -> int:
    """Falling factorial a^{underline k} = a(a-1)...(a-k+1)."""
    result: int = 1
    for i in range(k):
        result *= (a - i)
    return result


def count_antipodal_maps(m: int, n: int) -> int:
    """Exact number of antipodal simplicial maps S^m -> S^n."""
    return falling_factorial(n + 1, m + 1) * (2 ** (m + 1))


def count_table(max_m: int, max_n: int) -> List[List[int]]:
    """Full count table for 0 <= m <= max_m, 0 <= n <= max_n."""
    return [[count_antipodal_maps(m, n) for n in range(max_n + 1)]
            for m in range(max_m + 1)]

