from itertools import permutations, product
from typing import Iterator, List, Tuple

Vertex = Tuple[int, int]          # (axis, sign in {+1, -1})
AntipodalMap = List[Vertex]       # positive-vertex data: image of (i, +1)


def antipodal_maps(m: int, n: int) -> Iterator[AntipodalMap]:
    """Yield every antipodal simplicial map S^m -> S^n via the structure theorem:
    an injection of the m+1 source axes into the n+1 target axes, plus a free
    sign on each source axis."""
    for axis_injection in permutations(range(n + 1), m + 1):
        for sign_vector in product((+1, -1), repeat=m + 1):
            yield [(axis_injection[i], sign_vector[i]) for i in range(m + 1)]


def full_vertex_map(pos_data: AntipodalMap, m: int) -> dict:
    """Extend positive-vertex data to all 2(m+1) vertices by equivariance."""
    mapping = {}
    for i in range(m + 1):
        axis, sign = pos_data[i]
        mapping[(i, +1)] = (axis, sign)
        mapping[(i, -1)] = (axis, -sign)   # antipode
    return mapping

