from typing import Optional


def exists_antipodal_map(m: int, n: int) -> bool:
    """Existence dichotomy: a map S^m -> S^n exists iff m <= n."""
    return m <= n


def coindex(n: int, cap: int = 10_000) -> int:
    """coind(S^n): largest source dimension m with a map S^m -> S^n."""
    best = -1
    for m in range(cap + 1):
        if exists_antipodal_map(m, n):
            best = m
        else:
            break
    return best


def index(m: int, cap: int = 10_000) -> Optional[int]:
    """ind(S^m): smallest target dimension n with a map S^m -> S^n."""
    for n in range(cap + 1):
        if exists_antipodal_map(m, n):
            return n
    return None


def index_coindex_gap(n: int) -> int:
    """The index-coindex gap of S^n (always 0 for cross-polytope spheres)."""
    return (index(n) or 0) - coindex(n)
